import {renderPlan,layerDefs,filterLayer} from './plan-renderer.mjs';
import {readProject,readPlanPreferences} from './project-store.mjs';
import {makeZip} from './zip-store.mjs';
const $=id=>document.getElementById(id);let project=null,previewKey='base',busy=false;
const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1800;
function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function options(key){return {...project,isolated:key,mode:key==='black'?'black':'general',transparent:$('exportTransparent').checked,metadata:$('exportMetadata').checked};}
function draw(target,key){renderPlan(target,options(key));if(!$('exportMetadata').checked){const c=target.getContext('2d');c.font='16px Arial';c.fillStyle='#35434b';c.fillText('© OpenStreetMap contributors · ODbL',50,target.height-30);}}
function preview(key=previewKey){if(!project)return;previewKey=key;$('previewTitle').textContent=layerDefs.find(d=>d.key===key)?.name||key;draw($('layerPreview'),key);}
function chosen(){return [...document.querySelectorAll('[data-export-layer]:checked')].map(x=>x.dataset.exportLayer);}
function counts(){const n=chosen().length;$('exportCount').textContent=n+' из '+layerDefs.length+' слоёв';$('downloadZip').disabled=busy||!n;}
function geojson(key){return {type:'FeatureCollection',name:'atlas-'+key,source:'© OpenStreetMap contributors, ODbL https://www.openstreetmap.org/copyright',downloaded_at:project.downloadedAt,selection_bbox:[project.bounds[1],project.bounds[0],project.bounds[3],project.bounds[2]],note:'Original OSM geometry; coordinates WGS84 longitude,latitude; geometry may extend beyond selection. Cartographic symbols and inferred widths are not stored as measured geometry.',features:filterLayer(project.features,key)};}
function pngBlob(target){return new Promise((resolve,reject)=>target.toBlob(blob=>blob?resolve(blob):reject(Error('Не удалось создать PNG')),'image/png'));}
function lock(value){busy=value;document.querySelectorAll('button,input').forEach(el=>el.disabled=value);counts();}
async function action(fn){if(busy)return;lock(true);try{await fn();}catch(e){$('exportStatus').textContent='Ошибка экспорта: '+e.message;}finally{lock(false);}}
function card(def){const el=document.createElement('article');el.className='export-card';const top=document.createElement('div');top.className='export-card-top';const check=document.createElement('input');check.type='checkbox';check.checked=true;check.dataset.exportLayer=def.key;check.setAttribute('aria-label','Включить в ZIP: '+def.name);check.onchange=counts;const swatch=document.createElement('span');swatch.className='swatch';swatch.style.backgroundColor=def.color;const title=document.createElement('h3');title.textContent=def.name;top.append(check,swatch,title);const count=document.createElement('div');count.className='count';count.textContent=filterLayer(project.features,def.key).length+' объектов источника';const desc=document.createElement('p');desc.textContent=def.description;const controls=document.createElement('div');controls.className='card-actions';for(const [label,fn] of [['PNG ↓',()=>action(async()=>{draw(canvas,def.key);save(await pngBlob(canvas),'atlas-'+def.key+'.png');$('exportStatus').textContent='PNG: '+def.name+'. Размер и положение участка совпадают с другими слоями.';})],['GeoJSON ↓',()=>save(new Blob([JSON.stringify(geojson(def.key),null,2)],{type:'application/geo+json'}),'atlas-'+def.key+'.geojson')],['Просмотр',()=>preview(def.key)]]){const button=document.createElement('button');button.textContent=label;button.setAttribute('aria-label',label+' — '+def.name);button.onclick=fn;controls.append(button);}el.append(top,count,desc,controls);return el;}
async function load(){try{project=await readProject();if(!project?.bounds||!Array.isArray(project.features))throw Error('Загрузите участок на главной странице в этом браузере.');$('exportEmpty').hidden=true;$('exportWorkspace').hidden=false;const [s,w,n,e]=project.bounds;$('projectSummary').textContent=((s+n)/2).toFixed(6)+', '+((w+e)/2).toFixed(6)+' · '+(project.side**2/1e6).toFixed(2)+' км² · данные '+new Date(project.downloadedAt).toLocaleDateString('ru-RU');$('layerCards').replaceChildren(...layerDefs.map(card));counts();preview();}catch(e){$('exportWorkspace').hidden=true;$('exportEmpty').hidden=false;$('emptyMessage').textContent=e.message;}}
$('refreshProject').onclick=load;$('exportTransparent').onchange=()=>preview();$('exportMetadata').onchange=()=>preview();$('selectAll').onclick=()=>{document.querySelectorAll('[data-export-layer]').forEach(x=>x.checked=true);counts();};$('selectNone').onclick=()=>{document.querySelectorAll('[data-export-layer]').forEach(x=>x.checked=false);counts();};
$('downloadComposite').onclick=()=>action(async()=>{renderPlan(canvas,{...project,...readPlanPreferences(),transparent:false,metadata:true});save(await pngBlob(canvas),'atlas-composite.png');$('exportStatus').textContent='Собранный план экспортирован с настройками страницы «Планы».';});
$('downloadZip').onclick=()=>action(async()=>{const keys=chosen(),files=[];for(let i=0;i<keys.length;i++){const key=keys[i];$('exportStatus').textContent='Подготовка '+(i+1)+' / '+keys.length+': '+layerDefs.find(d=>d.key===key).name;await new Promise(r=>setTimeout(r,0));draw(canvas,key);files.push({name:'png/atlas-'+key+'.png',data:new Uint8Array(await (await pngBlob(canvas)).arrayBuffer())});files.push({name:'geojson/atlas-'+key+'.geojson',data:JSON.stringify(geojson(key),null,2)});}files.push({name:'README.json',data:JSON.stringify({title:'АТЛАС — отдельные слои',source:'© OpenStreetMap contributors',license:'ODbL https://www.openstreetmap.org/copyright',downloadedAt:project.downloadedAt,selectionBounds:project.bounds,boundsOrder:'south,west,north,east',png:{width:1600,height:1800,aligned:true,georeferenced:false,transparent:$('exportTransparent').checked,metadata:$('exportMetadata').checked},geojson:'WGS84 longitude,latitude; original uncut feature geometry',layers:keys,compositeSettings:readPlanPreferences(),notes:['Планы схематычны, не являются геодезической съёмкой.','Функциональное использование по OSM, не юридические зоны ПЗЗ.','Ширины линий и символы деревьев могут быть условными.']},null,2)});save(makeZip(files),'atlas-layers.zip');$('exportStatus').textContent='Готово: '+keys.length+' отдельных PNG, '+keys.length+' GeoJSON и описание источников в ZIP.';});
load();

